actionConfiguration.body:
select *
from public.save_event_proposal_secure(
	'{{ appsmith.user.email }}'::text,

	{{
	Number(
		appsmith.store.proposal_save_request
		?.proposal_id || 0
	)
	}}::bigint,

	'{{ appsmith.store.current_client_id }}'::uuid,

	'{{
	JSON.stringify(
		appsmith.store.proposal_save_request
		?.menus || []
	).replaceAll("'", "''")
	}}'::jsonb,

	{{
	appsmith.store.proposal_save_request
	?.active !== false
	? 'true'
	: 'false'
	}}::boolean
);
